DO $migration$ DECLARE definition text; BEGIN definition:=pg_get_functiondef('public.hg_event_payout_action(uuid,uuid,uuid,text,jsonb)'::regprocedure); IF position('IF p_action=''cancel'' AND e.organizer_id=p_actor AND r.state=''pending'' THEN' IN definition)=0 THEN RAISE EXCEPTION 'Unexpected payout cancellation guard';END IF; definition:=replace(definition,'IF p_action=''cancel'' AND e.organizer_id=p_actor AND r.state=''pending'' THEN','IF p_action=''cancel'' AND e.organizer_id=p_actor AND r.state=''cancelled'' THEN RETURN to_jsonb(r);END IF; IF p_action=''cancel'' AND e.organizer_id=p_actor AND r.state=''pending'' THEN');EXECUTE definition;END $migration$;

